            }
          ]
        }
      }
    ],
    "concepts": [
      {
        "concept": "number ready",
        "block": "given",
        "service": "calc",
        "references": [
          {
            "element": {
              "page": "Calc",
              "role": "textbox",
              "name": "Number"
            }
          }
        ],
        "does": "Enter the given number into the Number field."
      },
      {
        "concept": "number result",
        "block": "then",
        "service": "calc",
        "references": [
          {
            "element": {
              "page": "Calc",
              "role": "textbox",
              "name": "Number"
            }
          }
        ],
        "does": "Compare the displayed Number text with the expected result."
      },
      {
        "concept": "halve",
        "block": "when",
        "service": "calc",
        "references": [
          {
            "element": {
              "page": "Calc",
              "role": "button",
              "name": "Halve"
            }
          },
          {
            "element": {
              "page": "Calc",
              "role": "textbox",
              "name": "Idempotency key"
            }
          }
        ],
        "does": "Set Idempotency key to a fresh label for the requested halving and press Halve once. For a repeated request, reuse the label and press Halve again; Number must stay unchanged."
      }
    ],
    "terms": [
      {
        "term": "idempotency key",
        "technical": "The text value typed into the Calc page 'Idempotency key' textbox, which the page sends with the halve request",
        "observed_by": "The when step definition fills the Calc 'Idempotency key' textbox with the key named in the step, then presses Halve"
      }
    ]
  }
}
